import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Prop,
	State,
	Watch,
	forceUpdate,
	h,
} from "@stencil/core";

import { hasSlot } from "../../utils/slot";
import {
	generateButtonOnlyClipboard,
	generateClipBoardActionTooltip,
	generateClipBoardOverFlowLabelTooltip,
	generateClipboardActionPopover,
	generateFormClipboard,
	generateIconOnlyClipboard,
} from "./copyclipboard.render";
import { executeBrowserCopy } from "./copyclipboard.util";

/**
 * @since 0.0.6
 * @status stable
 *
 * @data-testid copyClipBoard-copy-button - The control that copies the current value to the clipboard.
 *
 * @part main-container - The component's main container.
 * @part value -The value of the copy clipboard.
 * @part icon-button - The icon copy button
 * @part copy-button - The button containing icon + copy text
 * @part content - The content of the tooltip
 *
 * @slot copy-label - The label for the copy button. (in normal and button-only mode)
 * @slot tooltip-hovered - The content to display when the tooltip is hovered. (in normal mode)
 * @slot tooltip-clicked - The content to display when the tooltip is clicked. (in normal mode)
 *
 * @slot copy-icon - The icon for the copy button. (in icon only mode)
 */

type I18n = {
	copy: string;
	copyToClipboard: string;
	copiedToClipboard: string;
};

const defaultI18n: I18n = {
	copy: "Copy",
	copyToClipboard: "Copy to Clipboard",
	copiedToClipboard: "Copied to Clipboard",
};

@Component({
	tag: "hbr-copyclipboard",
	styleUrl: "copyclipboard.scss",
	shadow: true,
})
export class HbrCopyclipboard {
	tooltipRef: HTMLHbrTooltipElement;
	popoverRef: HTMLHbrPopoverElement;
	labelOverflowTooltipRef: HTMLHbrTooltipElement;

	/** value to be copied */
	@Prop() value = "";

	/** The clipboard's label. Alternatively, you can use the label slot. */
	@Prop() label = "";

	/**  The clipboard's size. */
	@Prop({ reflect: true }) size: "small" | "medium" | "large" = "medium";

	/** To show clipboard with icon only. */
	@Prop({ reflect: true }) iconOnly: boolean;

	/** To show only the copy button with its icon and label. Since v2.18.62 */
	@Prop({ reflect: true }) buttonOnly: boolean;

	/** aria-label. deprecated candidate. use aria instead. */
	@Prop() arialabel: string;

	/** Attributes related to screen readers. */
	@Prop() aria: { label: string };

	/** To use hbr-truncate component in label */
	@Prop() truncate = true;

	/** The i18n (internationalization) key-value pairs. */
	@Prop() i18n: I18n;

	@State() hasLabelSlot = false;

	/** popover visible state */
	@State() popoverVisible = false;

	/** tooltip visible state */
	@State() tooltipVisible = false;

	@Element() host: HTMLHbrCopyclipboardElement;

	/** Emitted when the content is copied. */
	@Event({ eventName: "hbr-copy" }) hbrCopy: EventEmitter;

	@Watch("label")
	handleLabelChange() {
		this.hasLabelSlot = hasSlot(this.host, "label");
	}

	connectedCallback() {
		this.host.ownerDocument.addEventListener(
			"click",
			this.hideTooltipAndPopover,
		);
	}

	disconnectedCallback() {
		this.host.ownerDocument.removeEventListener(
			"click",
			this.hideTooltipAndPopover,
		);
	}
	// this is required to ensure tooltip/popover has ref after first render
	componentDidLoad() {
		forceUpdate(this);
	}

	handleMouseEnter = (event) => {
		const { currentTarget } = event;
		this.showTooltip(currentTarget);
	};

	handleMouseLeave = (event) => {
		this.hideTooltipAndPopover(event);
	};

	handleFocus = (event) => {
		const { currentTarget } = event;
		this.showTooltip(currentTarget);
	};

	handleBlur = (event) => {
		this.hideTooltipAndPopover(event);
	};

	handleClick = (event) => {
		const { currentTarget } = event;
		executeBrowserCopy(this.value)
			.then(() => {
				this.showPopover(currentTarget);
				this.hbrCopy.emit(event);
			})
			.catch((error) => {
				console.warn(`There was an error copying the text. ${error}`);
			});
	};

	showTooltip = (anchoringElement) => {
		if (this.tooltipRef && this.popoverRef && anchoringElement) {
			this.tooltipRef.anchor = anchoringElement;
			this.popoverVisible = false;
			// this.tooltipRef.style.display = "block";
			this.tooltipRef.classList.remove(
				"copyClipboard__floating-content_invisible",
			);
			this.tooltipVisible = true;
		}
	};

	showPopover = (anchoringElement) => {
		if (this.tooltipRef && this.popoverRef && anchoringElement) {
			this.popoverRef.anchor = anchoringElement;
			this.tooltipVisible = false;

			// to deal with tooltip shows up sometimes while popover is visible
			// this.tooltipRef.style.display = "none";
			this.tooltipRef.classList.add(
				"copyClipboard__floating-content_invisible",
			);
			this.popoverVisible = true;
		}
	};

	hideTooltipAndPopover = (event) => {
		const { target } = event;
		if (target !== this.host) {
			this.popoverVisible = false;
			this.tooltipVisible = false;
		}
	};

	render() {
		const i18n = {
			...this.i18n,
			...defaultI18n,
		};

		const aria = {
			...{ label: `copy: ${this.value}` }, // default
			...(this.arialabel && { label: this.arialabel }),
			...this.aria,
		};

		return (
			<Host>
				{this.buttonOnly
					? generateButtonOnlyClipboard(
							this.handleMouseEnter,
							this.handleMouseLeave,
							this.handleFocus,
							this.handleBlur,
							this.handleClick,
							this.size,
							aria?.label,
							i18n?.copy,
					  )
					: this.iconOnly
					  ? generateIconOnlyClipboard(
								this.handleMouseEnter,
								this.handleMouseLeave,
								this.handleFocus,
								this.handleBlur,
								this.handleClick,
								this.size,
								aria?.label,
						  )
					  : generateFormClipboard(
								this.label,
								this.hasLabelSlot,
								this.size,
								aria?.label,
								i18n?.copy,
								this.value,
								this.handleMouseEnter,
								this.handleMouseLeave,
								this.handleFocus,
								this.handleBlur,
								this.handleClick,
								this.labelOverflowTooltipRef,
								this.truncate,
						  )}

				{generateClipBoardOverFlowLabelTooltip((el) => {
					this.labelOverflowTooltipRef = el;
				}, this.value)}
				{generateClipBoardActionTooltip(
					(el) => {
						this.tooltipRef = el;
					},
					this.tooltipVisible,
					i18n?.copyToClipboard,
				)}
				{generateClipboardActionPopover(
					(el) => {
						this.popoverRef = el;
					},
					this.popoverVisible,
					i18n?.copiedToClipboard,
				)}
			</Host>
		);
	}
}
