import { h } from "@stencil/core";
import { alertsPositiveSmall, copy } from "../../../icons";
import FormControl from "../../functional-components/form-control/form-control";

import { generateShortID } from "../../utils/function-helper";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
const customSystemIcons = getBootstrapConfig()?.systemIcons;

const generateClipBoardOverFlowLabelTooltip = (refCallback, textContent) => {
	return (
		<hbr-tooltip ref={refCallback} enablePopover={true}>
			<div slot="content">{textContent}</div>
		</hbr-tooltip>
	);
};

const generateClipBoardActionTooltip = (
	refCallback,
	isVisible,
	textContent,
) => {
	return (
		<hbr-tooltip
			ref={refCallback}
			part="tooltip"
			class="copyClipboard__floating-content copyClipboard__action-tooltip"
			open={isVisible}
			enablePopover={true}
		>
			<div slot="content">
				<slot name="tooltip-hovered">
					<div>{textContent}</div>
				</slot>
			</div>
		</hbr-tooltip>
	);
};

const generateClipboardActionPopover = (
	refCallback,
	isVisible,
	textContent,
) => {
	return (
		<hbr-popover
			enablePopover={true}
			ref={refCallback}
			part="popover"
			class="copyClipboard__floating-content copyClipboard__action-popover"
			open={isVisible}
		>
			<div slot="content" part="content" class="copyClipboard__content">
				<slot name="tooltip-clicked">
					<hbr-icon
						asset={
							customSystemIcons?.["alerts-positive-small"] ||
							alertsPositiveSmall
						}
						size="16px"
						sentiment="success"
					/>
					<div>{textContent}</div>
				</slot>
			</div>
		</hbr-popover>
	);
};

const generateButtonOnlyClipboard = (
	handleMouseEnter,
	handleMouseLeave,
	handleFocus,
	handleBlur,
	handleClick,
	size,
	arialabel,
	i18nCopy,
) => {
	return (
		<hbr-button
			variant="text"
			onMouseEnter={handleMouseEnter}
			onMouseLeave={handleMouseLeave}
			onFocus={handleFocus}
			onBlur={handleBlur}
			onClick={handleClick}
			data-testid="copyClipBoard-copy-button"
			arialabel={arialabel}
			part="copy-button"
			exportparts="base:button-base"
			size={size}
		>
			<hbr-icon
				slot="prefix"
				asset={customSystemIcons?.copy || copy}
				size={size === "small" ? "14px" : "16px"}
				part="icon-button"
			/>
			<slot name="copy-label">
				<span class="copyClipboard__button-text">{i18nCopy}</span>
			</slot>
		</hbr-button>
	);
};

const generateIconOnlyClipboard = (
	handleMouseEnter,
	handleMouseLeave,
	handleFocus,
	handleBlur,
	handleClick,
	size,
	arialabel,
) => {
	return (
		<hbr-button
			variant="text"
			onMouseEnter={handleMouseEnter}
			onMouseLeave={handleMouseLeave}
			onFocus={handleFocus}
			onBlur={handleBlur}
			onClick={handleClick}
			data-testid="copyClipBoard-copy-button"
			arialabel={arialabel}
			part="copy-button"
			exportparts="base:button-base"
			size={size}
		>
			<slot name="copy-icon">
				<hbr-icon
					class={"copyClipboard__icon-only"}
					asset={customSystemIcons?.copy || copy}
					size={size === "small" ? "14px" : "16px"}
					part="icon-button"
				/>
			</slot>
		</hbr-button>
	);
};

const generateFormClipboard = (
	label,
	hasLabelSlot,
	size,
	arialabel,
	i18nCopy,
	value,
	handleMouseEnter,
	handleMouseLeave,
	handleFocus,
	handleBlur,
	handleClick,
	tooltipRef,
	truncate,
) => {
	return (
		<FormControl
			inputId={`copyClipboard-${generateShortID()}`}
			label={label}
			labelId={`copyClipboard-label-${generateShortID()}`}
			hasLabelSlot={hasLabelSlot}
			helpTextId={""}
			helpText={""}
			hasHelpTextSlot={false}
			size={size}
			source={""}
			hasFocus={false}
			hasValue={false}
			hasError={false}
			isDisabled={false}
			isRequired={false}
		>
			<div
				class={{
					copyClipboard: true,

					// Sizes
					"copyClipboard--small": size === "small",
					"copyClipboard--medium": size === "medium",
					"copyClipboard--large": size === "large",
				}}
				part="main-container"
			>
				<div class="copyClipboard__value" part="value">
					{truncate ? (
						<hbr-truncation tooltipTarget={tooltipRef}>{value}</hbr-truncation>
					) : (
						value
					)}
				</div>
				<hbr-button
					variant="text"
					onMouseEnter={handleMouseEnter}
					onFocus={handleFocus}
					onBlur={handleBlur}
					onMouseLeave={handleMouseLeave}
					onClick={handleClick}
					data-testid="copyClipBoard-copy-button"
					arialabel={arialabel}
					class="copyClipboard__tooltip-button"
					part="copy-button"
					size={size}
				>
					<hbr-icon
						slot="prefix"
						asset={customSystemIcons?.copy || copy}
						part="icon-button"
					/>
					<slot name="copy-label">
						<span class="copyClipboard__button-text">{i18nCopy}</span>
					</slot>
				</hbr-button>
			</div>
		</FormControl>
	);
};

export {
	generateButtonOnlyClipboard,
	generateIconOnlyClipboard,
	generateFormClipboard,
	generateClipBoardOverFlowLabelTooltip,
	generateClipBoardActionTooltip,
	generateClipboardActionPopover,
};
